  HashSet<String> keep=new HashSet<>();for(Iterator<String> it=resources.keys();it.hasNext();)keep.add(resources.getJSONObject(it.next()).getString("blob"));for(File f:blobs.listFiles()==null?new File[0]:blobs.listFiles())if(!keep.contains(f.getName()))f.delete();return changed;
